class OpenstackException(Exception):
    pass


class AmbiguousInstanceName(Exception):
    pass


class ImageNotFound(Exception):
    """ OS image not found """


class OSSDKException(Exception):
    """ Base exception of OS SDK, occurs when e.g. found more than one image with provided name or id """


class NetworkNotFound(Exception):
    """ Network not found """


class InvalidStackOutput(Exception):
    """ Stack output is not valid """


class UploadFail(Exception):
    pass


class Timeout(Exception):
    pass


class InvalidStatus(Exception):
    pass
